define([], function() { const centreSelector = '#site-news-forum, #frontpage-course-list, #frontpage-available-course-list, ' + '#frontpage-category-names, #frontpage-category-combo, #frontpage-course-tiles, ' + '#frontpage-upcoming-events, .local-zsk-fp-element-section'; const pendingSelector = '.local-termine-frontpage-pending'; const getCentreSlotIndex = function(node) { let value = node.getAttribute('data-centre-slot-index'); if (value === null || value === '') { value = node.getAttribute('data-slot-index'); } return parseInt(value || '0', 10); }; const collectExisting = function(main) { const existing = []; main.querySelectorAll(centreSelector).forEach(function(el) { if (!el.closest(pendingSelector)) { existing.push(el); } }); return existing; }; const findCourseSearchBox = function(main) { const form = main.querySelector('form[action*="course/search"]'); if (!form) { return null; } return form.closest('.box') || form.parentElement; }; const placeFrontpageTermine = function() { const pending = document.getElementById('local-termine-frontpage-pending'); if (!pending) { return; } const main = document.querySelector('#region-main'); if (!main) { return; } const centreSlot = getCentreSlotIndex(pending); const existing = collectExisting(main); const ref = existing[centreSlot] || null; pending.removeAttribute('id'); pending.classList.remove('local-termine-frontpage-pending'); if (ref) { main.insertBefore(pending, ref); return; } if (centreSlot === 0) { const searchBox = findCourseSearchBox(main); if (searchBox && searchBox.parentElement === main) { if (searchBox.nextSibling) { main.insertBefore(pending, searchBox.nextSibling); } else { main.appendChild(pending); } return; } main.insertBefore(pending, main.firstChild); return; } main.appendChild(pending); }; const init = function() { if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', placeFrontpageTermine); } else { placeFrontpageTermine(); } }; return { init: init, }; });